// @FIGURE_CODE_BEGIN
// ── Element spec ──
// hyperboloid shell → LatheGeometry(profile, 64), MeshBasicMaterial #f3a878 opacity 0.45 DoubleSide
// meridian lines → 14 Line segments at azimuths 100°–260° (front-left), #d97742
// central axis → dashed Line (0,0,0)→(0,3.592,0), #444
// waist dashed line → dashed Line (-0.6,2,0)→(0.6,2,0), #444
// top rim → LineLoop circle y=3.592 r=0.72, #d97742
// waist circle → LineLoop circle y=2.0 r=0.6, #d97742
// base ring → LineLoop circle y=0 r=0.781, #d97742
// teal struts → 16 angled CylinderGeometry at base, #4db6ac
// dim arrow 72m → horizontal double-arrow at top, #111
// dim arrow 60m → horizontal double-arrow at waist, #111
// dim arrow 79.6m → vertical double-arrow right side, #111
// dim arrow 179.6m → vertical double-arrow far left, #111
// measurement ring → LineLoop at slider height, #e74c3c
// 2D profile → Line right-branch hyperbola in XY plane + 2D dim arrows

const S = 0.02; // world units per metre
const H_TOTAL = 179.6 * S; // 3.592
const H_WAIST = 100 * S;   // 2.0
const A_M = 30;  // waist radius in metres
const B_M = 120; // hyperbola b parameter in metres

function radiusAt(h_m) {
  return A_M * Math.sqrt(1 + ((h_m - 100) ** 2) / (B_M * B_M));
}
function radiusWorld(h_m) { return radiusAt(h_m) * S; }

// ── Profile points for LatheGeometry ──
const profilePts = [];
const N_PROF = 80;
for (let i = 0; i <= N_PROF; i++) {
  const h_m = (i / N_PROF) * 179.6;
  const r = radiusWorld(h_m);
  profilePts.push(new THREE.Vector2(r, h_m * S));
}

// ── 3D Shell (LatheGeometry) ──
const shellGeo = new THREE.LatheGeometry(profilePts, 64);
const shellMat = new THREE.MeshBasicMaterial({
  color: 0xf3a878, transparent: true, opacity: 0.45, side: THREE.DoubleSide
});
const shell = new THREE.Mesh(shellGeo, shellMat);
scene.add(shell);

// ── Meridian contour lines (front-left azimuths) ──
const meridianGroup = new THREE.Group();
const N_MER = 14;
for (let i = 0; i < N_MER; i++) {
  const az = THREE.MathUtils.degToRad(100 + (i / (N_MER - 1)) * 160);
  const pts = [];
  for (let j = 0; j <= N_PROF; j++) {
    const h_m = (j / N_PROF) * 179.6;
    const r = radiusWorld(h_m);
    pts.push(new THREE.Vector3(r * Math.cos(az), h_m * S, r * Math.sin(az)));
  }
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const line = new THREE.Line(geo, new THREE.LineBasicMaterial({ color: 0xd97742 }));
  meridianGroup.add(line);
}
scene.add(meridianGroup);

// ── Central vertical dashed axis ──
const axisGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, H_TOTAL, 0)
]);
const axisMat = new THREE.LineDashedMaterial({ color: 0x444444, dashSize: 0.08, gapSize: 0.05 });
const axisLine = new THREE.Line(axisGeo, axisMat);
axisLine.computeLineDistances();
scene.add(axisLine);

// ── Horizontal dashed line at waist ──
const waistDashGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-0.6, H_WAIST, 0), new THREE.Vector3(0.6, H_WAIST, 0)
]);
const waistDashMat = new THREE.LineDashedMaterial({ color: 0x444444, dashSize: 0.06, gapSize: 0.04 });
const waistDash = new THREE.Line(waistDashGeo, waistDashMat);
waistDash.computeLineDistances();
scene.add(waistDash);

// ── Circles: top rim, waist, base ──
function makeCircle(y, r, color) {
  const pts = [];
  for (let i = 0; i <= 64; i++) {
    const a = (i / 64) * Math.PI * 2;
    pts.push(new THREE.Vector3(r * Math.cos(a), y, r * Math.sin(a)));
  }
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  return new THREE.Line(geo, new THREE.LineBasicMaterial({ color }));
}
const topRim = makeCircle(H_TOTAL, 0.72, 0xd97742);
const waistCircle = makeCircle(H_WAIST, 0.6, 0xd97742);
const baseRing = makeCircle(0, radiusWorld(0), 0xd97742);
scene.add(topRim, waistCircle, baseRing);

// ── Teal support struts ──
const strutGroup = new THREE.Group();
const N_STRUTS = 16;
const strutGeo = new THREE.CylinderGeometry(0.012, 0.012, 0.28, 6);
const strutMat = new THREE.MeshBasicMaterial({ color: 0x4db6ac });
for (let i = 0; i < N_STRUTS; i++) {
  const az = (i / N_STRUTS) * Math.PI * 2;
  const rBase = radiusWorld(0);
  const strut = new THREE.Mesh(strutGeo, strutMat);
  const x = rBase * Math.cos(az);
  const z = rBase * Math.sin(az);
  strut.position.set(x * 0.92, 0.14, z * 0.92);
  // Angle outward
  strut.rotation.z = 0.25 * Math.cos(az);
  strut.rotation.x = -0.25 * Math.sin(az);
  strutGroup.add(strut);
}
scene.add(strutGroup);

// ── Dimension arrow helper ──
function makeArrow(start, end, color = 0x111111) {
  const group = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(end, start);
  const len = dir.length();
  dir.normalize();
  const geo = new THREE.BufferGeometry().setFromPoints([start, end]);
  group.add(new THREE.Line(geo, new THREE.LineBasicMaterial({ color })));
  // Arrowheads
  const headLen = 0.06;
  const headW = 0.03;
  for (const [pt, d] of [[start, dir.clone().negate()], [end, dir.clone()]]) {
    const perp = new THREE.Vector3();
    if (Math.abs(d.y) > 0.9) perp.set(1, 0, 0);
    else perp.set(0, 1, 0);
    perp.cross(d).normalize();
    const tip = pt.clone().add(d.clone().multiplyScalar(headLen));
    const p1 = pt.clone().add(perp.clone().multiplyScalar(headW));
    const p2 = pt.clone().add(perp.clone().multiplyScalar(-headW));
    const triGeo = new THREE.BufferGeometry().setFromPoints([tip, p1, p2, tip]);
    const triMat = new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide });
    group.add(new THREE.Mesh(triGeo, triMat));
  }
  return group;
}

// ── 3D Dimension arrows ──
const dimGroup3D = new THREE.Group();
// 72m across top (offset in z for visibility)
const dim72 = makeArrow(
  new THREE.Vector3(-0.72, H_TOTAL + 0.15, 0),
  new THREE.Vector3(0.72, H_TOTAL + 0.15, 0)
);
dimGroup3D.add(dim72);
// 60m across waist
const dim60 = makeArrow(
  new THREE.Vector3(-0.6, H_WAIST, 0),
  new THREE.Vector3(0.6, H_WAIST, 0)
);
dimGroup3D.add(dim60);
// 79.6m vertical right side
const dim796 = makeArrow(
  new THREE.Vector3(0.9, H_WAIST, 0),
  new THREE.Vector3(0.9, H_TOTAL, 0)
);
dimGroup3D.add(dim796);
// 179.6m vertical far left
const dim1796 = makeArrow(
  new THREE.Vector3(-1.1, 0, 0),
  new THREE.Vector3(-1.1, H_TOTAL, 0)
);
dimGroup3D.add(dim1796);
scene.add(dimGroup3D);

// ── Measurement ring (slider-driven) ──
let measureH = 100; // metres
const measureGroup = new THREE.Group();
scene.add(measureGroup);

function updateMeasureRing(h_m) {
  measureH = h_m;
  // Clear old
  while (measureGroup.children.length) {
    const c = measureGroup.children.pop();
    c.geometry?.dispose(); c.material?.dispose();
  }
  const r = radiusWorld(h_m);
  const y = h_m * S;
  // Ring
  const pts = [];
  for (let i = 0; i <= 64; i++) {
    const a = (i / 64) * Math.PI * 2;
    pts.push(new THREE.Vector3(r * Math.cos(a), y, r * Math.sin(a)));
  }
  const ringGeo = new THREE.BufferGeometry().setFromPoints(pts);
  const ring = new THREE.Line(ringGeo, new THREE.LineBasicMaterial({ color: 0xe74c3c, linewidth: 2 }));
  measureGroup.add(ring);
  // Horizontal diameter line
  const diaGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-r, y, 0), new THREE.Vector3(r, y, 0)
  ]);
  const diaLine = new THREE.Line(diaGeo, new THREE.LineBasicMaterial({ color: 0xe74c3c }));
  measureGroup.add(diaLine);
  // Update readout
  const diam = 2 * radiusAt(h_m);
  document.getElementById('diameterReadout').textContent =
    `Diameter at h=${h_m.toFixed(1)} m: ${diam.toFixed(1)} m`;
  // Update label position
  if (measureLabel) measureLabel.pos.set(r + 0.15, y, 0);
  if (measureLabel) measureLabel.div.innerHTML = `${diam.toFixed(1)} m`;
}

// ── 2D Profile geometry ──
const profile2DGroup = new THREE.Group();
profile2DGroup.visible = false;
scene.add(profile2DGroup);

// Right branch hyperbola curve
const prof2DPts = [];
for (let i = 0; i <= 100; i++) {
  const h_m = (i / 100) * 179.6;
  const r = radiusWorld(h_m);
  prof2DPts.push(new THREE.Vector3(r, h_m * S, 0));
}
const prof2DGeo = new THREE.BufferGeometry().setFromPoints(prof2DPts);
const prof2DLine = new THREE.Line(prof2DGeo, new THREE.LineBasicMaterial({ color: 0xd97742, linewidth: 2 }));
profile2DGroup.add(prof2DLine);

// Left branch (mirror) for the 2D profile
const prof2DLpts = [];
for (let i = 0; i <= 100; i++) {
  const h_m = (i / 100) * 179.6;
  const r = radiusWorld(h_m);
  prof2DLpts.push(new THREE.Vector3(-r, h_m * S, 0));
}
const prof2DLGeo = new THREE.BufferGeometry().setFromPoints(prof2DLpts);
const prof2DLLine = new THREE.Line(prof2DLGeo, new THREE.LineBasicMaterial({ color: 0xd97742, linewidth: 2 }));
profile2DGroup.add(prof2DLLine);

// 2D dimension arrows
const dim2D72 = makeArrow(
  new THREE.Vector3(-0.72, H_TOTAL + 0.15, 0),
  new THREE.Vector3(0.72, H_TOTAL + 0.15, 0)
);
profile2DGroup.add(dim2D72);
const dim2D60 = makeArrow(
  new THREE.Vector3(-0.6, H_WAIST, 0),
  new THREE.Vector3(0.6, H_WAIST, 0)
);
profile2DGroup.add(dim2D60);
const dim2D796 = makeArrow(
  new THREE.Vector3(0.9, H_WAIST, 0),
  new THREE.Vector3(0.9, H_TOTAL, 0)
);
profile2DGroup.add(dim2D796);
const dim2D1796 = makeArrow(
  new THREE.Vector3(-1.1, 0, 0),
  new THREE.Vector3(-1.1, H_TOTAL, 0)
);
profile2DGroup.add(dim2D1796);

// 2D dashed axis
const axis2DGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, H_TOTAL, 0)
]);
const axis2DMat = new THREE.LineDashedMaterial({ color: 0x444444, dashSize: 0.08, gapSize: 0.05 });
const axis2DLine = new THREE.Line(axis2DGeo, axis2DMat);
axis2DLine.computeLineDistances();
profile2DGroup.add(axis2DLine);

// 2D waist dashed
const waist2DGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-0.6, H_WAIST, 0), new THREE.Vector3(0.6, H_WAIST, 0)
]);
const waist2DMat = new THREE.LineDashedMaterial({ color: 0x444444, dashSize: 0.06, gapSize: 0.04 });
const waist2DLine = new THREE.Line(waist2DGeo, waist2DMat);
waist2DLine.computeLineDistances();
profile2DGroup.add(waist2DLine);

// ── Labels ──
addLabel('72 m', new THREE.Vector3(0, H_TOTAL + 0.25, 0), { fontSize: '12px', bold: true });
addLabel('60 m', new THREE.Vector3(0, H_WAIST + 0.12, 0), { fontSize: '12px', bold: true });
addLabel('79.6 m', new THREE.Vector3(1.05, (H_WAIST + H_TOTAL) / 2, 0), { fontSize: '12px', bold: true });
addLabel('179.6 m', new THREE.Vector3(-1.3, H_TOTAL / 2, 0), { fontSize: '12px', bold: true });

// Measurement label
const measureLabel = addLabel('60.0 m', new THREE.Vector3(0.75, H_WAIST, 0), {
  fontSize: '11px', color: '#e74c3c', bold: true
});

// ── View toggle ──
let is3D = true;
const viewBtn = document.getElementById('viewToggle');
viewBtn.addEventListener('click', () => {
  is3D = !is3D;
  viewBtn.textContent = is3D ? '3D Tower' : '2D Profile';
  viewBtn.classList.toggle('active', is3D);
  shell.visible = is3D;
  meridianGroup.visible = is3D;
  strutGroup.visible = is3D;
  topRim.visible = is3D;
  waistCircle.visible = is3D;
  baseRing.visible = is3D;
  dimGroup3D.visible = is3D;
  axisLine.visible = is3D;
  waistDash.visible = is3D;
  profile2DGroup.visible = !is3D;
  measureGroup.visible = true;
  if (is3D) {
    setCameraView({ projection: 'perspective', azimuthDeg: 35, elevationDeg: 18, heightFraction: 0.7 });
