function makeArrow(start, end, color = 0x111111) {
  const group = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(end, start);
  const len = dir.length();
  dir.normalize();
  const geo = new THREE.BufferGeometry().setFromPoints([start, end]);
  group.add(new THREE.Line(geo, new THREE.LineBasicMaterial({ color })));
  // Arrowheads
  const headLen = 0.06;
  const headW = 0.03;
  for (const [pt, d] of [[start, dir.clone().negate()], [end, dir.clone()]]) {
    const perp = new THREE.Vector3();
    if (Math.abs(d.y) > 0.9) perp.set(1, 0, 0);
    else perp.set(0, 1, 0);
    perp.cross(d).normalize();
    const tip = pt.clone().add(d.clone().multiplyScalar(headLen));
    const p1 = pt.clone().add(perp.clone().multiplyScalar(headW));
    const p2 = pt.clone().add(perp.clone().multiplyScalar(-headW));
    const triGeo = new THREE.BufferGeometry().setFromPoints([tip, p1, p2, tip]);
    const triMat = new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide });
    group.add(new THREE.Mesh(triGeo, triMat));
  }
  return group;
