const S = 0.02;
const H_TOTAL = 179.6 * S;
const H_WAIST = 100 * S;
const A_M = 30;
const B_M = 120;

function radiusAt(h_m) {
  return A_M * Math.sqrt(1 + ((h_m - 100) ** 2) / (B_M * B_M));
}
function radiusWorld(h_m) { return radiusAt(h_m) * S; }

// ── Profile points ──
const N_PROF = 80;
const profilePts = [];
for (let i = 0; i <= N_PROF; i++) {
  const h_m = (i / N_PROF) * 179.6;
  profilePts.push(new THREE.Vector2(radiusWorld(h_m), h_m * S));
}

// ══════════════════════════════════════════════════════════
// 2D PROFILE GROUP (default view)
// ══════════════════════════════════════════════════════════
const profile2DGroup = new THREE.Group();
scene.add(profile2DGroup);

// ── Right-half solid fill ──
const fillShape = new THREE.Shape();
fillShape.moveTo(0, 0);
for (let i = 0; i <= N_PROF; i++) {
  const h_m = (i / N_PROF) * 179.6;
  fillShape.lineTo(radiusWorld(h_m), h_m * S);
}
fillShape.lineTo(0, H_TOTAL);
fillShape.lineTo(0, 0);
const fillGeo = new THREE.ShapeGeometry(fillShape, 32);
const fillMat = new THREE.MeshBasicMaterial({ color: 0xf3a878, side: THREE.DoubleSide, transparent: true, opacity: 0.85 });
const fillMesh = new THREE.Mesh(fillGeo, fillMat);
