// ── Left-half meridian contour lines ──
const N_MER_2D = 18;
for (let i = 1; i <= N_MER_2D; i++) {
  const cosT = i / (N_MER_2D + 1); // 0..1 fraction
  const pts = [];
  for (let j = 0; j <= N_PROF; j++) {
    const h_m = (j / N_PROF) * 179.6;
    const r = radiusWorld(h_m) * cosT;
    pts.push(new THREE.Vector3(-r, h_m * S, 0));
  }
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const line = new THREE.Line(geo, new THREE.LineBasicMaterial({ color: 0xd97742 }));
  profile2DGroup.add(line);
}

// ── Left outer edge (the leftmost meridian = full profile mirrored) ──
const leftEdgePts = [];
for (let j = 0; j <= N_PROF; j++) {
  const h_m = (j / N_PROF) * 179.6;
  leftEdgePts.push(new THREE.Vector3(-radiusWorld(h_m), h_m * S, 0));
}
const leftEdgeGeo = new THREE.BufferGeometry().setFromPoints(leftEdgePts);
const leftEdgeLine = new THREE.Line(leftEdgeGeo, new THREE.LineBasicMaterial({ color: 0xd97742 }));
profile2DGroup.add(leftEdgeLine);

// ── Right outer edge ──
const rightEdgePts = [];
for (let j = 0; j <= N_PROF; j++) {
  const h_m = (j / N_PROF) * 179.6;
  rightEdgePts.push(new THREE.Vector3(radiusWorld(h_m), h_m * S, 0));
}
const rightEdgeGeo = new THREE.BufferGeometry().setFromPoints(rightEdgePts);
const rightEdgeLine = new THREE.Line(rightEdgeGeo, new THREE.LineBasicMaterial({ color: 0xd97742 }));
profile2DGroup.add(rightEdgeLine);

// ── 2D Central dashed axis ──
const axis2DGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, -0.1, 0), new THREE.Vector3(0, H_TOTAL + 0.1, 0)
]);
const axis2DMat = new THREE.LineDashedMaterial({ color: 0x444444, dashSize: 0.08, gapSize: 0.05 });
const axis2DLine = new THREE.Line(axis2DGeo, axis2DMat);
axis2DLine.computeLineDistances();
profile2DGroup.add(axis2DLine);

// ── 2D Horizontal dashed line at waist ──
const waist2DGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-0.65, H_WAIST, 0), new THREE.Vector3(0.65, H_WAIST, 0)
]);
const waist2DMat = new THREE.LineDashedMaterial({ color: 0x444444, dashSize: 0.06, gapSize: 0.04 });
const waist2DLine = new THREE.Line(waist2DGeo, waist2DMat);
waist2DLine.computeLineDistances();
profile2DGroup.add(waist2DLine);

// ── Dimension arrow helper ──
function makeArrow(start, end, color = 0x111111) {
  const group = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(end, start);
  const len = dir.length();
  dir.normalize();
  const geo = new THREE.BufferGeometry().setFromPoints([start, end]);
  group.add(new THREE.Line(geo, new THREE.LineBasicMaterial({ color })));
  const headLen = 0.06;
  const headW = 0.03;
  for (const [pt, d] of [[start, dir.clone().negate()], [end, dir.clone()]]) {
    const perp = new THREE.Vector3();
    if (Math.abs(d.y) > 0.9) perp.set(1, 0, 0);
    else perp.set(0, 1, 0);
    perp.cross(d).normalize();
    const tip = pt.clone().add(d.clone().multiplyScalar(headLen));
    const p1 = pt.clone().add(perp.clone().multiplyScalar(headW));
    const p2 = pt.clone().add(perp.clone().multiplyScalar(-headW));
    const triGeo = new THREE.BufferGeometry().setFromPoints([tip, p1, p2, tip]);
    const triMat = new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide });
    group.add(new THREE.Mesh(triGeo, triMat));
  }
  return group;
}

// ── 2D Dimension arrows ──
// 72m across top
const dim2D72 = makeArrow(
  new THREE.Vector3(-0.72, H_TOTAL + 0.18, 0),
  new THREE.Vector3(0.72, H_TOTAL + 0.18, 0)
);
profile2DGroup.add(dim2D72);
// Extension lines for 72m
const ext72L = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-0.72, H_TOTAL, 0), new THREE.Vector3(-0.72, H_TOTAL + 0.22, 0)
  ]), new THREE.LineBasicMaterial({ color: 0x111111 }));
const ext72R = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0.72, H_TOTAL, 0), new THREE.Vector3(0.72, H_TOTAL + 0.22, 0)
  ]), new THREE.LineBasicMaterial({ color: 0x111111 }));
profile2DGroup.add(ext72L, ext72R);

// 60m across waist
const dim2D60 = makeArrow(
  new THREE.Vector3(-0.6, H_WAIST, 0),
  new THREE.Vector3(0.6, H_WAIST, 0)
);
profile2DGroup.add(dim2D60);

// 79.6m vertical right side (from waist to top)
const dim2D796 = makeArrow(
  new THREE.Vector3(0.95, H_WAIST, 0),
  new THREE.Vector3(0.95, H_TOTAL, 0)
);
profile2DGroup.add(dim2D796);
// Extension lines for 79.6m
const ext796T = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0.72, H_TOTAL, 0), new THREE.Vector3(1.0, H_TOTAL, 0)
  ]), new THREE.LineBasicMaterial({ color: 0x111111 }));
const ext796B = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0.6, H_WAIST, 0), new THREE.Vector3(1.0, H_WAIST, 0)
  ]), new THREE.LineBasicMaterial({ color: 0x111111 }));
profile2DGroup.add(ext796T, ext796B);

// 179.6m full height far left
const dim2D1796 = makeArrow(
  new THREE.Vector3(-1.2, 0, 0),
  new THREE.Vector3(-1.2, H_TOTAL, 0)
);
profile2DGroup.add(dim2D1796);
// Extension lines for 179.6m
const ext1796T = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-0.78, H_TOTAL, 0), new THREE.Vector3(-1.25, H_TOTAL, 0)
  ]), new THREE.LineBasicMaterial({ color: 0x111111 }));
const ext1796B = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-0.78, 0, 0), new THREE.Vector3(-1.25, 0, 0)
  ]), new THREE.LineBasicMaterial({ color: 0x111111 }));
profile2DGroup.add(ext1796T, ext1796B);

// ── 2D Teal struts at base ──
const strut2DGroup = new THREE.Group();
const N_STRUTS_2D = 12;
for (let i = 0; i < N_STRUTS_2D; i++) {
  const x = -0.7 + (i / (N_STRUTS_2D - 1)) * 1.4;
  const strutGeo = new THREE.CylinderGeometry(0.008, 0.008, 0.22, 6);
  const strutMat = new THREE.MeshBasicMaterial({ color: 0x4db6ac });
  const strut = new THREE.Mesh(strutGeo, strutMat);
  strut.position.set(x, 0.11, 0);
  strut.rotation.z = 0.15 * (x > 0 ? -1 : 1);
  strut2DGroup.add(strut);
}
profile2DGroup.add(strut2DGroup);

// ══════════════════════════════════════════════════════════
// 3D TOWER GROUP
// ══════════════════════════════════════════════════════════
const tower3DGroup = new THREE.Group();
tower3DGroup.visible = false;
scene.add(tower3DGroup);

// ── 3D Shell ──
const shellGeo = new THREE.LatheGeometry(profilePts, 64);
const shellMat = new THREE.MeshBasicMaterial({
  color: 0xf3a878, transparent: true, opacity: 0.45, side: THREE.DoubleSide
});
const shell = new THREE.Mesh(shellGeo, shellMat);
tower3DGroup.add(shell);

// ── 3D Meridian lines ──
const meridianGroup = new THREE.Group();
const N_MER = 14;
for (let i = 0; i < N_MER; i++) {
  const az = THREE.MathUtils.degToRad(100 + (i / (N_MER - 1)) * 160);
  const pts = [];
  for (let j = 0; j <= N_PROF; j++) {
    const h_m = (j / N_PROF) * 179.6;
    const r = radiusWorld(h_m);
    pts.push(new THREE.Vector3(r * Math.cos(az), h_m * S, r * Math.sin(az)));
  }
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const line = new THREE.Line(geo, new THREE.LineBasicMaterial({ color: 0xd97742 }));
  meridianGroup.add(line);
}
tower3DGroup.add(meridianGroup);

// ── 3D Central axis ──
const axis3DGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, H_TOTAL, 0)
]);
const axis3DMat = new THREE.LineDashedMaterial({ color: 0x444444, dashSize: 0.08, gapSize: 0.05 });
const axis3DLine = new THREE.Line(axis3DGeo, axis3DMat);
axis3DLine.computeLineDistances();
tower3DGroup.add(axis3DLine);

// ── 3D Waist dashed ──
const waist3DGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-0.6, H_WAIST, 0), new THREE.Vector3(0.6, H_WAIST, 0)
]);
const waist3DMat = new THREE.LineDashedMaterial({ color: 0x444444, dashSize: 0.06, gapSize: 0.04 });
const waist3DLine = new THREE.Line(waist3DGeo, waist3DMat);
waist3DLine.computeLineDistances();
tower3DGroup.add(waist3DLine);

// ── 3D Circles ──
function makeCircle(y, r, color) {
  const pts = [];
  for (let i = 0; i <= 64; i++) {
    const a = (i / 64) * Math.PI * 2;
    pts.push(new THREE.Vector3(r * Math.cos(a), y, r * Math.sin(a)));
  }
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  return new THREE.Line(geo, new THREE.LineBasicMaterial({ color }));
}
const topRim = makeCircle(H_TOTAL, 0.72, 0xd97742);
const waistCircle = makeCircle(H_WAIST, 0.6, 0xd97742);
const baseRing = makeCircle(0, radiusWorld(0), 0xd97742);
tower3DGroup.add(topRim, waistCircle, baseRing);

// ── 3D Teal struts ──
const strutGroup = new THREE.Group();
const N_STRUTS = 16;
const strutGeo3D = new THREE.CylinderGeometry(0.012, 0.012, 0.28, 6);
const strutMat3D = new THREE.MeshBasicMaterial({ color: 0x4db6ac });
for (let i = 0; i < N_STRUTS; i++) {
  const az = (i / N_STRUTS) * Math.PI * 2;
  const rBase = radiusWorld(0);
  const strut = new THREE.Mesh(strutGeo3D, strutMat3D);
  const x = rBase * Math.cos(az);
  const z = rBase * Math.sin(az);
  strut.position.set(x * 0.92, 0.14, z * 0.92);
  strut.rotation.z = 0.25 * Math.cos(az);
  strut.rotation.x = -0.25 * Math.sin(az);
  strutGroup.add(strut);
}
tower3DGroup.add(strutGroup);

// ── 3D Dimension arrows ──
const dimGroup3D = new THREE.Group();
const dim3D72 = makeArrow(
  new THREE.Vector3(-0.72, H_TOTAL + 0.18, 0),
  new THREE.Vector3(0.72, H_TOTAL + 0.18, 0)
);
dimGroup3D.add(dim3D72);
const dim3D60 = makeArrow(
  new THREE.Vector3(-0.6, H_WAIST, 0),
  new THREE.Vector3(0.6, H_WAIST, 0)
);
dimGroup3D.add(dim3D60);
const dim3D796 = makeArrow(
  new THREE.Vector3(0.95, H_WAIST, 0),
  new THREE.Vector3(0.95, H_TOTAL, 0)
);
dimGroup3D.add(dim3D796);
const dim3D1796 = makeArrow(
  new THREE.Vector3(-1.2, 0, 0),
  new THREE.Vector3(-1.2, H_TOTAL, 0)
);
dimGroup3D.add(dim3D1796);
tower3DGroup.add(dimGroup3D);

// ══════════════════════════════════════════════════════════
// MEASUREMENT LINE (shared between modes)
// ══════════════════════════════════════════════════════════
const measureGroup = new THREE.Group();
scene.add(measureGroup);

let measureH = 100;

function updateMeasureRing(h_m) {
  measureH = h_m;
  while (measureGroup.children.length) {
    const c = measureGroup.children.pop();
    c.geometry?.dispose(); c.material?.dispose();
  }
  const r = radiusWorld(h_m);
  const y = h_m * S;

  if (is3D) {
    // 3D ring
    const pts = [];
    for (let i = 0; i <= 64; i++) {
      const a = (i / 64) * Math.PI * 2;
      pts.push(new THREE.Vector3(r * Math.cos(a), y, r * Math.sin(a)));
    }
    const ringGeo = new THREE.BufferGeometry().setFromPoints(pts);
    const ring = new THREE.Line(ringGeo, new THREE.LineBasicMaterial({ color: 0xe74c3c }));
    measureGroup.add(ring);
    // Diameter line
    const diaGeo = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(-r, y, 0), new THREE.Vector3(r, y, 0)
    ]);
    measureGroup.add(new THREE.Line(diaGeo, new THREE.LineBasicMaterial({ color: 0xe74c3c })));
  } else {
    // 2D horizontal line
    const diaGeo = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(-r, y, 0), new THREE.Vector3(r, y, 0)
    ]);
    measureGroup.add(new THREE.Line(diaGeo, new THREE.LineBasicMaterial({ color: 0xe74c3c })));
  }

  const diam = 2 * radiusAt(h_m);
  document.getElementById('diameterReadout').textContent =
    `Diameter at h=${h_m.toFixed(1)} m: ${diam.toFixed(1)} m`;

  // Update label - offset vertically to avoid collision with "60 m" label
  const labelOffsetY = Math.abs(h_m - 100) < 5 ? 0.18 : 0.08;
  if (measureLabel) {
    measureLabel.pos.set(r + 0.12, y + labelOffsetY, 0);
    measureLabel.div.innerHTML = `${diam.toFixed(1)} m`;
  }
}

// ══════════════════════════════════════════════════════════
// LABELS
// ══════════════════════════════════════════════════════════
addLabel('72 m', new THREE.Vector3(0, H_TOTAL + 0.3, 0), { fontSize: '12px', bold: true });
addLabel('60 m', new THREE.Vector3(0, H_WAIST + 0.14, 0), { fontSize: '12px', bold: true });
addLabel('79.6 m', new THREE.Vector3(1.12, (H_WAIST + H_TOTAL) / 2, 0), { fontSize: '12px', bold: true });
addLabel('179.6 m', new THREE.Vector3(-1.42, H_TOTAL / 2, 0), { fontSize: '12px', bold: true });

// Measurement label (red, offset to avoid collision with 60m)
const measureLabel = addLabel('60.0 m', new THREE.Vector3(0.72, H_WAIST + 0.18, 0), {
  fontSize: '11px', color: '#e74c3c', bold: true
});

// ══════════════════════════════════════════════════════════
// VIEW TOGGLE
// ══════════════════════════════════════════════════════════
let is3D = false; // Start in 2D profile mode to match source
const viewBtn = document.getElementById('viewToggle');

function applyView() {
  viewBtn.textContent = is3D ? '3D Tower' : '2D Profile';
  viewBtn.classList.toggle('active', is3D);
  profile2DGroup.visible = !is3D;
  tower3DGroup.visible = is3D;
  updateMeasureRing(measureH);
  if (is3D) {
    setCameraView({ projection: 'perspective', azimuthDeg: 35, elevationDeg: 18, heightFraction: 0.7 });
  } else {
    setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 0, heightFraction: 0.75 });
  }
}

viewBtn.addEventListener('click', () => {
  is3D = !is3D;
  applyView();
});

// ── Height slider ──
const slider = document.getElementById('heightSlider');
slider.addEventListener('input', () => {
  updateMeasureRing(parseFloat(slider.value));
});

// ── Initial state: 2D profile ──
updateMeasureRing(100);
setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 0, heightFraction: 0.75 });

// ── Demo steps ──
window.goToStep = function(step) {
  if (step.state) {
    if (step.state.heightSlider !== undefined) {
      slider.value = step.state.heightSlider;
      updateMeasureRing(step.state.heightSlider);
    }
    if (step.state.viewToggle !== undefined) {
      const want3D = step.state.viewToggle === '3D Tower';
      if (is3D !== want3D) {
        is3D = want3D;
        applyView();
      }
    }
  }
};
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

